class LoginActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        enableEdgeToEdge()
        setContent {
            IT140P_SPARKTheme {
                Surface(
                    modifier = Modifier.fillMaxSize(),
                    color = LightColorScheme.background
                ) {
                    Login()
                }
            }
        }
    }
}

@Composable
fun Login() {
    val context = LocalContext.current
    val coroutineScope = rememberCoroutineScope()
    val passwordFocusRequester = remember { FocusRequester() }
    val focusManager = LocalFocusManager.current

    var username by remember { mutableStateOf("") }
    var password by remember { mutableStateOf("") }
    var usernameError by remember { mutableStateOf(false) }
    var passwordError by remember { mutableStateOf(false) }
    var usernameSupportingText by remember { mutableStateOf("*enter your MCL live email address") }
    var passwordSupportingText by remember { mutableStateOf("*enter your password") }

    val httpClient = remember {
        HttpClient(CIO) {
            install(ContentNegotiation) {
                json(Json {
                    ignoreUnknownKeys = true
                    prettyPrint = true
                    isLenient = true
                })
            }
        }
    }

    DisposableEffect(Unit) {
        onDispose {
            httpClient.close()
        }
    }

    Box(
        modifier = Modifier.fillMaxSize()
    ) {
        Image(
            painter = painterResource(id = R.drawable.login_bg),
            contentDescription = null,
            modifier = Modifier.fillMaxSize(),
            contentScale = ContentScale.Crop
        )
        Column(
            Modifier
                .navigationBarsPadding()
                .imePadding()
                .padding(24.dp)
                .fillMaxSize(),
            verticalArrangement = Arrangement.spacedBy(16.dp, alignment = Alignment.CenterVertically),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Text(
                "MMCL Spark",
                style = MaterialTheme.typography.headlineLarge,
                color = LightColorScheme.onBackground
            )
            OutlinedTextField(
                value = username,
                onValueChange = {
                    username = it
                    if (usernameError) {
                        usernameError = false
                        usernameSupportingText = "*enter your MCL live email address"
                    }
                },
                label = { Text("Email*", color = LightColorScheme.onBackground) },
                isError = usernameError,
                supportingText = {
                    Text(
                        usernameSupportingText,
                        color = if (usernameError) LightColorScheme.error else LightColorScheme.onBackground
                    )
                },
                trailingIcon = {
                    if (usernameError) {
                        Icon(
                            imageVector = Icons.Filled.Error,
                            contentDescription = "Error",
                            tint = LightColorScheme.error
                        )
                    }
                },
                modifier = Modifier.fillMaxWidth(),
                singleLine = true,
                keyboardOptions = KeyboardOptions(
                    keyboardType = KeyboardType.Email,
                    imeAction = ImeAction.Next
                ),
                keyboardActions = KeyboardActions(
                    onNext = { passwordFocusRequester.requestFocus() }
                ),
                textStyle = MaterialTheme.typography.bodyLarge.copy(color = LightColorScheme.onBackground),
                colors = lightModeOutlinedTextFieldColors()
            )
            OutlinedTextField(
                value = password,
                onValueChange = {
                    password = it
                    if (passwordError) {
                        passwordError = false
                        passwordSupportingText = "*enter your password"
                    }
                },
                label = { Text("Password*", color = LightColorScheme.onBackground) },
                isError = passwordError,
                supportingText = {
                    Text(
                        passwordSupportingText,
                        color = if (passwordError) LightColorScheme.error else LightColorScheme.onBackground
                    )
                },
                trailingIcon = {
                    if (passwordError) {
                        Icon(
                            imageVector = Icons.Filled.Error,
                            contentDescription = "Error",
                            tint = LightColorScheme.error
                        )
                    }
                },
                modifier = Modifier.fillMaxWidth().focusRequester(passwordFocusRequester),
                visualTransformation = PasswordVisualTransformation(),
                singleLine = true,
                keyboardOptions = KeyboardOptions(
                    keyboardType = KeyboardType.Password,
                    imeAction = ImeAction.Done
                ),
                keyboardActions = KeyboardActions(
                    onDone = {
                        val hasError = validateAndSetErrors(
                            username,
                            password,
                            onUsernameError = { msg ->
                                usernameError = true
                                usernameSupportingText = msg
                            },
                            onPasswordError = {
                                passwordError = true
                                passwordSupportingText = "Password is required"
                            }
                        )
                        if (!hasError) {
                            focusManager.clearFocus()
                            coroutineScope.launch {
                                performLoginAttempt(
                                    httpClient,
                                    username,
                                    password,
                                    context
                                )
                            }
                        }
                    }
                ),
                textStyle = MaterialTheme.typography.bodyLarge.copy(color = LightColorScheme.onBackground),
                colors = lightModeOutlinedTextFieldColors()
            )
            Button(
                onClick = {
                    val hasError = validateAndSetErrors(
                        username,
                        password,
                        onUsernameError = { msg ->
                            usernameError = true
                            usernameSupportingText = msg
                        },
                        onPasswordError = {
                            passwordError = true
                            passwordSupportingText = "Password is required"
                        }
                    )
                    if (!hasError) {
                        // Use runBlocking to ensure coroutine completes before proceeding
                        kotlinx.coroutines.runBlocking {
                            performLoginAttempt(
                                httpClient,
                                username,
                                password,
                                context
                            )
                        }
                    }
                },
                modifier = Modifier.fillMaxWidth()
            ) {
                Text("Sign In", Modifier.padding(vertical = 8.dp))
            }
        }
    }
}

private suspend fun performLoginAttempt(
    httpClient: HttpClient,
    username: String,
    passwordPlain: String,
    context: Context
) {
    if (username.isBlank() || passwordPlain.isBlank()) {
        showToast(context, "Please enter both username and password")
        return
    }

    val (status, studentIdOrMessage) = loginUser(httpClient, username, passwordPlain)

    when (status) {
        "success" -> {
            showToast(context, "Login successful")
            val intent = Intent(context, MainActivity::class.java).apply {
                putExtra("USERNAME", username)
                putExtra("STUDENT_ID", studentIdOrMessage)
            }
            context.startActivity(intent)
            (context as? ComponentActivity)?.finish()
        }
        "error" -> {
            showToast(context, studentIdOrMessage ?: "Login failed")
        }
        else -> {
            showToast(context, "An unexpected error occurred")
        }
    }
}

private suspend fun loginUser(
    httpClient: HttpClient,
    username: String,
    passwordPlain: String
): Pair<String, String?> {
    return try {
        val fullUrl = "${SERVER_URL}student_login_json.php"

        val response: HttpResponse = httpClient.post(fullUrl) {
            contentType(ContentType.Application.FormUrlEncoded)
            setBody(
                listOf(
                    "StudentUsername" to username,
                    "StudentPassword" to passwordPlain
                ).formUrlEncode()
            )
        }

        val responseBodyString = response.bodyAsText()

        val jsonResponse = Json.parseToJsonElement(responseBodyString).jsonObject
        val status = jsonResponse["status"]?.jsonPrimitive?.content ?: "error"
        val message = jsonResponse["message"]?.jsonPrimitive?.content ?: "Unknown error"
        val studentId = jsonResponse["student_id"]?.jsonPrimitive?.content

        if (status == "success") {
            Pair(status, studentId)
        } else {
            Pair(status, message)
        }
    } catch (_: Exception) {
        Pair("error", "An unexpected error occurred")
    }
}

fun showToast(context: Context, message: CharSequence) {
    Toast.makeText(context, message, Toast.LENGTH_SHORT).show()
}

// Add helper function for validation
private fun validateAndSetErrors(
    username: String,
    password: String,
    onUsernameError: (String) -> Unit,
    onPasswordError: () -> Unit
): Boolean {
    var hasError = false
    if (username.isBlank()) {
        onUsernameError("Email is required")
        hasError = true
    } else if (!username.endsWith("@live.mcl.edu.ph")) {
        onUsernameError("Email must be a valid MCL live account")
        hasError = true
    }
    if (password.isBlank()) {
        onPasswordError()
        hasError = true
    }
    return hasError
}

@Composable
fun lightModeOutlinedTextFieldColors(): TextFieldColors = OutlinedTextFieldDefaults.colors(
    focusedTextColor = LightColorScheme.onBackground,
    unfocusedTextColor = LightColorScheme.onBackground,
    disabledTextColor = LightColorScheme.onBackground.copy(alpha = 0.38f),
    errorTextColor = LightColorScheme.error,
    focusedContainerColor = LightColorScheme.background,
    unfocusedContainerColor = LightColorScheme.background,
    disabledContainerColor = LightColorScheme.background,
    errorContainerColor = LightColorScheme.background,
    cursorColor = LightColorScheme.primary,
    errorCursorColor = LightColorScheme.error,
    focusedBorderColor = LightColorScheme.primary,
    unfocusedBorderColor = LightColorScheme.outline,
    disabledBorderColor = LightColorScheme.outline.copy(alpha = 0.38f),
    errorBorderColor = LightColorScheme.error,
    focusedLabelColor = LightColorScheme.primary,
    unfocusedLabelColor = LightColorScheme.onBackground,
    disabledLabelColor = LightColorScheme.onBackground.copy(alpha = 0.38f),
    errorLabelColor = LightColorScheme.error
)

