enum class Weekday(val display: String) {
    Monday("Monday"),
    Tuesday("Tuesday"),
    Wednesday("Wednesday"),
    Thursday("Thursday"),
    Friday("Friday"),
    Saturday("Saturday"),
    Sunday("Sunday");
}

data class SimpleScheduleEvent(
    val name: String,
    val day: Weekday,
    val startHour: Float,
    val endHour: Float,
    val color: Color,
    val onColor: Color
)

@Serializable
data class Schedule(
    @SerialName("CourseID") val courseId: String,
    @SerialName("CourseCode") val courseCode: String,
    @SerialName("Day") val day: String?,
    @SerialName("StartTime") val startTime: String?,
    @SerialName("EndTime") val endTime: String?
)

@Serializable
data class ScheduleSearchResponse(
    val status: String,
    val message: String? = null,
    val data: List<Schedule>? = null
)

fun parseTimeToFloat(time: String): Float {
    val formatter = DateTimeFormatter.ofPattern("h:mm a", Locale.ENGLISH)
    val localTime = LocalTime.parse(time, formatter)
    return localTime.hour + localTime.minute / 60f
}

fun mapDayStringToEnum(day: String): Weekday? {
    return when (day.lowercase()) {
        "monday" -> Weekday.Monday
        "tuesday" -> Weekday.Tuesday
        "wednesday" -> Weekday.Wednesday
        "thursday" -> Weekday.Thursday
        "friday" -> Weekday.Friday
        "saturday" -> Weekday.Saturday
        "sunday" -> Weekday.Sunday
        else -> null
    }
}

// --- Conversion function ---
fun scheduleToSimpleScheduleEvent(schedule: Schedule, color: Color, onColor: Color): SimpleScheduleEvent? {
    val dayEnum = schedule.day?.let { mapDayStringToEnum(it) } ?: return null
    val start = schedule.startTime?.let {
        try { parseTimeToFloat(it) } catch (e: Exception) { return null }
    } ?: return null
    val end = schedule.endTime?.let {
        try { parseTimeToFloat(it) } catch (e: Exception) { return null }
    } ?: return null
    return SimpleScheduleEvent(
        name = schedule.courseCode,
        color = color,
        onColor = onColor,
        day = dayEnum,
        startHour = start,
        endHour = end
    )
}

@Composable
fun StudentScheduleTimetable(
    context: Context,
    studentID: String,
    httpClient: HttpClient,
    screen: String
) {
    var events by remember { mutableStateOf<List<SimpleScheduleEvent>>(emptyList()) }
    var isLoading by remember { mutableStateOf(true) }
    val containerColor = MaterialTheme.colorScheme.primaryContainer

    LaunchedEffect(studentID, containerColor, screen) {
        isLoading = true
        val schedule = fetchStudentSchedule(context, httpClient, studentID, screen)
        events = schedule.mapIndexedNotNull { idx, sched ->
            scheduleToSimpleScheduleEvent(
                sched,
                CourseEventColors.getContainerColor(idx),
                CourseEventColors.getOnContainerColor(idx)
            )
        }
        isLoading = false
    }

    if (!isLoading) {
        WeeklySchedule(events = mergeAdjacentEventsWithText(events))
    }
}

